// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testRegression_property() public {
        c.init(address(0x1), address(0x2), address(0x3));

        address recipient = address(0x4);
        uint amount = 100;
        vm.prank(address(0x5));
        c.newGrantProposal(recipient, amount);

        address proposedAddress = address(0x6);
        vm.prank(address(0x7));
        c.newAddressProposal(proposedAddress, "GRANT");

        vm.prank(address(0x5));
        c.voteProposal(1);

        vm.prank(address(0x7));
        c.voteProposal(2);

        vm.prank(address(0x5));
        c.cancelProposal(1, 2);

        assertTrue(c.proposalCount() == 2, "proposalCount should be 2 in reference");
    }
}
